def authorize(claims, expected_issuer, expected_audience, required_scope, now):
    if claims.get('iss') != expected_issuer: return 401
    if claims.get('aud') != expected_audience: return 401
    if now >= claims.get('exp', 0) or now < claims.get('nbf', 0): return 401
    if required_scope not in claims.get('scope', '').split(): return 403
    return {'status': 200, 'subject': claims['sub']}
